CREATE COLUMN TABLE "TEST_AP"."MABV" ("absEntry" INTEGER CS_INT NOT NULL , "pkgName" NVARCHAR(200) NOT NULL , "fileName" NVARCHAR(200), "imprtDate" LONGDATE CS_LONGDATE, "pkgPath" NVARCHAR(200), PRIMARY KEY ("absEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "MABV_PKG_NAME" ON "TEST_AP"."MABV" ( "pkgName" ASC )